function art(id=p.avatar,mini=false){const look=currentLook(p,id),outfit=STYLES.find(x=>x.id===look.style)||STYLES[0];return `<span class="sprite ${mini?'mini':''}" data-avatar="${id}" data-travel-style="${outfit.id}" data-hat="${look.hat||''}" data-glasses="${look.glasses||''}" style="--clothes:${outfit.color};--eye-top:${[39,39,43,41,38,43,45,50,44,46,44,43][id]}%" aria-hidden="true"><canvas width="120" height="120"></canvas></span>`;}
