function animate(ts){requestAnimationFrame(animate);if(ts-lastPaint<(j?.hotelLocation==='neighborhood'?33:90))return;const frameDt=Math.min(.2,(ts-lastPaint)/1000);lastPaint=ts;paintAirportLook(ts);paintCinema(ts);paintCabinPreview(ts);paintWindowLook();paintAnimalFeeding(ts);drawTravelerElements(ts/1000);drawAnimalElements();travelSound.step(f?'flight':j?.stage||'home',musicPreview||f?.routeId||j?.routeId||(page==='boarding'?p.route:'home'));syncSoundButton();if(ts-lastRevenue>60000){lastRevenue=ts;const income=settleBlog(p);if(income){save();currencies();if(page==='blog')renderPage(true);}}if(f&&!f.completed){syncTime();resolveActivity();updateFlight();paintFlight();if(f.elapsed>=f.duration&&!pausedAt)arrival();if(ts-lastSave>5000){save();lastSave=ts;}}else if(j&&!j.completed){if(ts-lastSave>5000){save();lastSave=ts;}if(settleRide(j)){walkTarget=155;save();renderJourney();}if(!$('journey-screen').hidden)drawTravelScene($('travel-scene'),j,p,ts/1000,walkTarget);if(j.stage==='hotel'&&j.hotelLocation==='neighborhood'&&$('modal').hidden){const arrived=stepWalk(j,frameDt);if(arrived){save();enterNeighborhoodPlace(arrived);}}if(j.ride){const remain=Math.max(0,Math.ceil((j.ride.until-Date.now())/1000));if($('ride-time'))$('ride-time').textContent=remain+'초';if($('ride-fill'))$('ride-fill').style.width=Math.min(100,(Date.now()-j.ride.from)/6000*100)+'%';}};
 document.querySelectorAll('#home-avatar .sprite,#seat-avatar .sprite').forEach(el=>{const id=+el.dataset.avatar,frame=Math.floor(ts/2600)%2;el.style.backgroundPosition=`${((id%2)*2+frame)/3*100}% ${Math.floor(id/2)/5*100}%`;});}
window.addEventListener('resize',resizeCanvas);document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(backInsideGame())e.preventDefault();return;}if(e.key==='Tab'&&!$('modal').hidden){const buttons=[...$('modal-content').querySelectorAll('button:not(:disabled),input')];if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function backInsideGame(){if(j?.completed){j=null;home();return true;}if(!$('modal').hidden){close();return true;}if(f){pause();return true;}if(j&&!$('journey-screen').hidden){if($('journey-screen').classList.contains('scenery-only')){$('scene-look').click();return true;}$('journey-pause').click();return true;}if(page){home();return true;}return false;}
window.flightCafeBack=backInsideGame;
function persistAway(){travelSound.suspend();if(pausedAt&&f&&!f.completed){f.startedAt+=Date.now()-pausedAt;pausedAt=Date.now();}syncTime();save();}
