for(const [id,icon] of [['wardrobe-icon','bow'],['book-icon','book'],['help-icon','lamp'],['blog-icon','book'],['updates-icon','ticket'],['camera-icon','camera'],['meal-icon','bento'],['rest-icon','rest'],['read-icon','book']])$(id).innerHTML=pixelIcon(icon);
