function rideHTML(){const local=localFlavor(j.routeId),id=j.ride?.id;const name=j.stage==='to-hotel'?cityTransitName(j.routeId,id):(j.stage==='to-airport'?TO_AIRPORT:TO_HOTEL).find(t=>t.id===id)?.name||'이동';return `<h2>${j.stage==='to-airport'?'공항으로 가는 길':'숙소로 가는 길'}</h2><p class="intro">${name}에 앉아 차창을 보고 있어요.<br>${j.stage==='to-airport'?'집이 조금씩 멀어져요.':'새로운 도시의 골목이 지나가요.'}</p><div class="ride-card"><strong id="ride-time">6초</strong><p>잠깐의 차창 여행</p><div class="ride-track"><i id="ride-fill"></i></div></div><button id="road-photo" class="secondary">차창의 풍경 기억하기</button>`;}
function renderJourney(keep=false){if(!j||j.completed)return;const top=$('journey-body').scrollTop;$('home').hidden=true;$('page').hidden=true;$('flight').hidden=true;$('journey-screen').hidden=false;page='';$('journey-route').textContent=`우리 집 → ${route(j.routeId).name}`;$('journey-place').textContent={packing:'우리 집 · 출발 준비','to-airport':'공항 가는 길',airport:'인천 국제공항 · 탑승 준비',arrival:j.entry?.passed?'도착 공항 · 수하물 찾기':'도착 공항 · 입국 수속','to-hotel':'숙소 가는 길',hotel:j.checkedIn?j.hotelLocation==='neighborhood'?route(j.routeId).name+' · 동네 산책':j.hotelLocation==='lobby'?'숙소 · 로비':'숙소 · 내 객실':'숙소 · 체크인'}[j.stage]||'';$('journey-cash').innerHTML=moneyHTML(j.budget);currencies();const tripWish=wishProgress({...j,preparedCount:packingGoals(j).filter(Boolean).length},f);$('journey-wish').hidden=!tripWish;if(tripWish)$('journey-wish').textContent=tripWish.wish.name+' '+tripWish.count+'/3';$('journey-track').innerHTML=journeyTrail();$('travel-scene').parentElement.dataset.map=String(j.stage==='hotel'&&j.checkedIn&&j.hotelLocation==='neighborhood');$('place-caption').textContent=j.stage==='packing'?'떠나기 전, 익숙한 나의 방':j.stage==='hotel'&&j.hotelLocation==='neighborhood'?'가게와 명소를 잇는 동네 골목':j.stage==='hotel'&&j.checkedIn?cityCaption(j.routeId).room:j.stage==='airport'?'인천 국제공항의 활주로와 탑승 게이트':j.stage==='arrival'?cityCaption(j.routeId).airport:j.stage==='hotel'?'열쇠를 받아, 오늘의 방으로':'차창으로 흘러가는 여행';
 if(j.stage==='packing'){ $('journey-card').innerHTML=packingHTML();groundFooter(`<button id="choose-outbound" class="primary" ${j.bag.includes('passport')&&j.bag.includes('phone')?'':'disabled'}>공항으로 가는 방법 고르기</button>`,'여권과 휴대폰은 필수예요. 물건을 누르면 챙기거나 뺄 수 있어요.');}
 else if(j.stage==='airport'){ $('journey-card').innerHTML=airportHTML();groundFooter(`<button id="board-journey" class="primary" ${j.airport.ticket&&j.airport.security?'':'disabled'}>게이트 ${destination(j.routeId).gate}에서 비행기 탑승</button>`,'수속을 마치면 바로 탑승해도 되고, 공항에서 시간을 보내도 좋아요.');}
 else if(j.stage==='arrival'){ $('journey-card').innerHTML=arrivalHTML();groundFooter('',j.entry?.passed?'짐을 찾은 뒤 숙소까지 이어서 여행해요.':'해외 여행의 첫 순서, 입국 수속을 마쳐요.');}
 else if(j.stage==='hotel'){ $('journey-card').innerHTML=hotelHTML();groundFooter(j.hotelLocation==='neighborhood'||j.hotelLocation==='lobby'?'<button id="return-room" class="primary">내 객실로 돌아가기</button>':`<button id="finish-journey" class="primary" ${j.checkedIn&&j.hotelTask?'':'disabled'}>오늘의 여행 완성하기</button>`,j.hotelLocation==='neighborhood'?'표시된 장소를 누르면 길을 따라 걸어요. 고른 동선에서 이야기를 만나요.':'산책과 휴식을 즐기고, 여행을 마칠 때 블로그에 남길 기억을 골라요.');}
 else{$('journey-card').innerHTML=rideHTML();groundFooter('','6초의 짧은 이동 후 다음 장소에 도착해요. 앱을 닫아도 이동은 이어져요.');}
 $('journey-body').scrollTop=keep?top:0;drawTravelScene($('travel-scene'),j,p,performance.now()/1000,walkTarget);}
function chooseOutbound(){modal(`<div class="eyebrow">ON THE WAY TO AIRPORT</div><h2 id="modal-title">어떻게 공항에 갈까요?</h2><p>남은 여행 경비 ${j.budget} · 집에서 챙긴 짐 무게 ${bagWeight(j)}<br>이동 뒤에는 체크인과 보안 검색에 13분이 필요해요.</p>${transportHTML(TO_AIRPORT)}<button class="secondary" data-close>짐을 조금 더 살펴보기</button>`);}
function passSecurity(){const result=airportAction(j,'security');if(result.ok){walkTarget=158;save();renderJourney(true);}if(result.message)toast(result.message);}
const SHOP_MENU_ART={coffee:['coffee-latte','coffee-matcha','coffee-cocoa'],restaurant:['restaurant-udon','restaurant-sandwich','restaurant-bibimbap'],postcard:['postcard-plane','postcard-cloud','postcard-stamp']};
const SHOP_MENUS={coffee:['바닐라 라테','따뜻한 말차','구름 코코아'],restaurant:['따뜻한 우동','채소 샌드위치','작은 비빔밥'],dutyfree:['작은 여행 향수','도시 초콜릿','토끼 키링'],postcard:['비행기 엽서','구름 엽서','공항 스탬프']};
function shopModal(id){if(id==='dutyfree'){shopCategory='magnet';dutyFreeModal();return;}if(id==='postcard'){airportLook();return;}const shop=AIRPORT_SHOPS.find(s=>s.id===id);if(!shop)return;walkTarget=280;modal(`<div class="eyebrow">AIRPORT LITTLE JOYS</div><h2 id="modal-title">${shop.name}</h2><p>${shop.description}<br>${shop.minutes}분 사용 · ${shop.cost} 경비 · 탑승까지 ${85-j.minutes}분</p><div class="transport-grid">${SHOP_MENUS[id].map((name,i)=>`<button class="transport-option" data-shop-order="${id}" data-order-index="${i}">${dutyProductArt(SHOP_MENU_ART[id]?.[i],48)||pixelIcon(shop.icon)}<span><strong>${name}</strong><small>${id==='postcard'?'기억으로 남기기':'이것으로 고르기'}</small></span></button>`).join('')}</div><button class="secondary" data-close>다른 곳 둘러보기</button>`);}
function immigrationModal(){entryPurpose=null;entryHotel=null;modal(`<div class="eyebrow">WELCOME TO ${route(j.routeId).code}</div><h2 id="modal-title">입국 수속</h2><p>여권을 제시했어요. 여행 목적과 예약한 숙소를 확인해요.</p><h3 class="section-title">이번 방문 목적</h3><div class="choice-row"><button class="choice" data-entry-purpose="holiday">여행</button><button class="choice" data-entry-purpose="transfer">환승</button></div><h3 class="section-title">예약한 숙소</h3><div class="transport-grid">${HOTELS.map((h,i)=>`<button class="transport-option" data-entry-hotel="${h.id}"><span><strong>${destination(j.routeId).hotelNames[i]}</strong><small>${h.name}</small></span></button>`).join('')}</div><button id="entry-submit" class="primary">확인하고 입국하기</button><button class="secondary" data-close>예약 다시 살펴보기</button>`);}
let entryPurpose=null,entryHotel=null;
let shopCategory='glasses';
function itemEffect(item){if(item.capacity)return `다음 여행 짐 용량 ${item.capacity} · 선택해서 사용`;if(item.category==='glasses')return '선택하면 안경 착용 · 비행 편안함 +5';if(item.category==='chocolate')return '편안함 +5 · 선물함에 수집';if(item.category==='liquor')return '여행 선물함에 수집';return '여행 선물함에 수집';}
function shoppingCard(item){const check=canPurchase(j,item.id),owned=p.collection[item.id]||0;return `<button class="shop-product" data-purchase="${item.id}" ${check.ok?'':'disabled'}><div class="product-art" style="--product-color:${item.color}">${productArt(item.id,72)}</div><strong>${item.name}</strong><small>${item.cost} 경비 · ${item.minutes}분<br>즐거움 +${item.joy}${item.comfort?' · 편안함 +'+item.comfort:''}${item.capacity?'<br>다음 여행 짐 용량 '+item.capacity:''}</small><span>${j.purchases?.includes(item.id)?'이번 여행 구매 완료':owned?'보유 '+owned+'개 · 하나 더 담기':'담기'}</span></button>`;}
function dutyFreeModal(){const stock=shopInventory(j),local=airportRegion(j),name=local==='incheon'?'인천':route(local).name;modal(`<div class="eyebrow">DUTY FREE · LITTLE TREASURES</div><h2 id="modal-title">${name} 공항 면세점</h2><div class="shop-wallet">남은 경비 ${j.budget}${j.stage==='airport'?' · 탑승까지 '+Math.max(0,85-j.minutes)+'분':''}</div><p>마그넷은 이 지역에서만 살 수 있어요.<br>숙소 이동비 10은 남겨두어요.</p><div class="shop-tabs">${SHOP_CATEGORIES.map(c=>`<button class="${shopCategory===c.id?'selected':''}" data-shop-category="${c.id}">${productArt(stock.find(x=>x.category===c.id)?.id,24)}<span>${c.name}</span></button>`).join('')}</div><p class="shop-effect">${shopCategory==='magnet'?name+' 한정 마그넷 · 수집한 기념품은 여행가방과 블로그에 남아요.':itemEffect(stock.find(x=>x.category===shopCategory))}</p><div class="shop-products">${stock.filter(x=>x.category===shopCategory).map(shoppingCard).join('')}</div><button class="secondary" data-close>${j.stage==='airport'?'게이트로 돌아가기':'도착 공항으로 돌아가기'}</button>`);}
function collectionHTML(){const owned=COLLECTION_ITEMS.filter(x=>p.collection[x.id]);return `<h3 class="section-title">면세점에서 모은 물건 · ${DUTY_ITEMS.filter(x=>p.collection[x.id]).length}/${DUTY_ITEMS.length}</h3><p class="intro">선물은 여행이 끝나도 남아요.<br>마그넷은 여행의 기억으로 모아요. 안경은 선택해서 사용해요.<br>예전에 산 가방·캐리어도 계속 사용할 수 있어요.<br>다음 여행 짐 용량 ${suitcaseCapacity(p)} · 기본 7</p>${owned.length?`<div class="collection-grid">${owned.map(item=>`<div class="collection-card"><div class="product-art" style="--product-color:${item.color}">${productArt(item.id,60)}</div><strong>${item.name}</strong><small>보유 ${p.collection[item.id]}개<br>${itemEffect(item)}</small>${['glasses','bag','case'].includes(item.category)?`<button data-equip-purchase="${item.id}" class="secondary ${p.equipped[item.category]===item.id?'selected':''}">${p.equipped[item.category]===item.id?'사용 중 · 빼기':'사용하기'}</button>`:''}</div>`).join('')}</div>`:'<div class="empty">공항 면세점에서 마음에 드는 물건을 골라보세요.</div>'}`;}
function completeJourney(){const r=finishJourney(p,j);if(!r)return;save();const hotel=destination(j.routeId).hotelNames[HOTELS.findIndex(h=>h.id===j.hotel)];modal(`<div class="eyebrow">HOME TO STAY · JOURNEY COMPLETE</div><h2 id="modal-title">${hotel}에 도착했어요</h2><div class="arrival-art">${art(p.avatar,true)}${pixelIcon('suitcase',36)}</div><p style="text-align:center">우리 집 → 공항 → 비행 → 도착 공항 → 숙소<br>짐을 챙긴 순간부터 객실에 들어오기까지<br>한 번의 여행을 끝냈어요.</p><div class="reward"><span>총 +${r.totalXP} XP</span><span>총 +${r.totalCoins}머니</span></div><p>비행 보상 포함 · 숙소 도착 보너스 ${r.xp} XP / ${r.coins}머니<br>필요한 짐 ${r.prepared}/2 · ${r.thrifty?'경비를 알뜰하게 썼어요':'여행 중 기분 좋은 소비를 했어요'}<br>${r.after>r.before?'Lv.'+r.after+' 여행자로 성장했어요.':''}</p>${r.wish?`<div class="wish-result">${r.wish.wish.name} · ${r.wish.count}/3<small>추가 ${r.wish.xp} XP · ${r.wish.coins}머니 · 총 보상에 포함</small></div>`:''}${r.post?`<div class="blog-settlement"><strong>여행 블로그에 새 글을 올렸어요</strong><span>광고 수입 +${r.post.income} 경비 · 읽음 ${r.post.views}</span><small>남은 경비 ${r.returned}을 지갑에 돌려놓았어요.${r.post.repayment?" 선지급 "+r.post.repayment+" 경비를 정산했어요.":""}<br>다음 여행 경비 ${p.blog.wallet}</small></div>`:""}<button id="trip-blog" class="secondary">이번 여행 블로그 보기</button><button id="trip-home" class="primary">집으로 돌아가기</button><button id="trip-book" class="secondary">이번 여행 수첩 보기</button>`,false);ping(1000);}
function stayRecords(){const visited=new Set(p.visitedRooms||[]);return `<div class="boarding-pass"><div><strong>집에서 숙소까지 ${p.journeys||0}회</strong><small>서로 다른 방 ${visited.size}/93 · 방을 누르면 기억을 펼쳐요.</small></div>${pixelIcon('suitcase',30)}</div>${p.stays?.length?`<h3 class="section-title">오늘의 방, 오늘의 기억</h3><div class="stay-album">${p.stays.map((s,i)=>`<button class="stay-card" data-stay="${i}" aria-label="${destinationLabel(s.route)} 숙소 여행 기록"><div class="stay-picture"><canvas width="180" height="120" data-stay-canvas="${i}"></canvas><span>${route(s.route).code}</span></div><strong>${destination(s.route).hotelNames[HOTELS.findIndex(h=>h.id===s.hotel)]}</strong><small>${destinationLabel(s.route)}<time>${new Date(s.date).toLocaleDateString('ko-KR')}</time></small><p>${destination(s.route).note}</p></button>`).join('')}</div>`:'<p class="intro">숙소에서 하루를 마치면, 그 방을 수첩에 담아요.<br>짐을 풀어 놓은 자리와 공항에서 고른 물건도 함께 남아요.</p>'}`;}
function drawStays(){if(!['passport','blog'].includes(page))return;const list=p.stays||[];environmentsReady([...new Set(list.flatMap(s=>s.departure==='night'?[s.hotel,s.hotel+'-night']:[s.hotel]))],list.map(s=>s.route)).then(()=>{document.querySelectorAll('[data-stay-canvas]').forEach(canvas=>{const record=list[+canvas.dataset.stayCanvas];if(record)drawStayMemory(canvas,record);});});}
function stayModal(index){const s=p.stays[index];if(!s)return;const hotel=destination(s.route).hotelNames[HOTELS.findIndex(h=>h.id===s.hotel)],transportName=id=>[...TO_AIRPORT,...TO_HOTEL].find(t=>t.id===id)?.name||'기억 속 이동';modal(`<div class="eyebrow">A ROOM I REMEMBER · ${route(s.route).code}</div><h2 id="modal-title">${hotel}</h2><canvas id="stay-detail" width="360" height="240" class="stay-detail"></canvas><p class="diary-note">${destination(s.route).note}</p><div class="diary-lines"><span>${new Date(s.date).toLocaleDateString('ko-KR')} · ${destinationLabel(s.route)}</span><span>${s.transport?transportName(s.transport.outbound)+' → 비행 → '+transportName(s.transport.inbound):'우리 집 → 공항 → 비행 → 숙소'}</span><span>필요한 짐 ${s.prepared}/2 · 남은 경비 ${s.budget}</span><span>${s.bag?.length?'챙긴 물건: '+s.bag.map(roomItemName).map(esc).join(' · '):''}</span>${Object.keys(s.purchases||{}).length?'<span>공항에서: '+Object.values(s.purchases).map(esc).join(' · ')+'</span>':''}${Object.keys(s.roomLayout||{}).length?'<span>방에 놓은 물건: '+Object.keys(s.roomLayout).map(roomItemName).map(esc).join(' · ')+'</span>':''}</div><button class="primary" data-close>수첩으로 돌아가기</button>`);environmentsReady(s.departure==='night'?[s.hotel,s.hotel+'-night']:[s.hotel],[s.route]).then(()=>{if($('stay-detail'))drawStayMemory($('stay-detail'),s);});}

$('journey-pause').onclick=()=>modal(`<div class="eyebrow">MY JOURNEY</div><h2 id="modal-title">잠시 쉬어갈까요?</h2><p>여행 기록은 자동으로 저장돼요.<br>앱을 다시 열면 지금 장소에서 이어갈 수 있어요.</p>${musicControls()}<button class="primary" data-close>계속 여행하기</button><button id="cancel-journey" class="secondary">이번 여행 취소하고 집으로</button>`);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.lodging){p.lodging=b.dataset.lodging;save();renderPage(true);return;}
 if(b.dataset.tripWish){p.tripWish=b.dataset.tripWish;if(!p.travelPlans[p.route])p.travelPlans[p.route]=planFor(p.route,p.tripWish);save();renderPage(true);return;}
 if(b.dataset.pack){const result=togglePack(j,b.dataset.pack);if(!result.ok)toast(result.message);else{walkTarget=['pajamas','coat','scarf'].includes(b.dataset.pack)?270:110;save();renderJourney(true);}return;}
 if(b.id==='choose-outbound'){chooseOutbound();return;}
 if(b.dataset.transport){const result=moveTrip(j,b.dataset.transport);if(!result.ok){toast(result.message);return;}close();save();walkTarget=155;renderJourney();return;}
 if(b.dataset.airport){const result=airportAction(j,b.dataset.airport);if(result.ok){walkTarget=70;save();renderJourney(true);}if(result.message)toast(result.message);return;}
 if(b.hasAttribute('data-security')){passSecurity();return;}
 if(b.dataset.shop){shopModal(b.dataset.shop);return;}
 if(b.dataset.shopCategory){shopCategory=b.dataset.shopCategory;dutyFreeModal();return;}
 if(b.dataset.purchase){purchaseDetail(b.dataset.purchase);return;}
 if(b.dataset.equipPurchase){if(shopItem(b.dataset.equipPurchase)?.category==='glasses'?wearPurchasedGlasses(p,b.dataset.equipPurchase):equipPurchase(p,b.dataset.equipPurchase)){save();renderPage(true);}return;}
 if(b.dataset.shopOrder){const type=b.dataset.shopOrder,index=+b.dataset.orderIndex,result=airportAction(j,type);if(result.ok){const name=SHOP_MENUS[type][index];j.orders={...(j.orders||{}),[type]:name};save();renderJourney(true);purchaseComplete(name,dutyProductArt(SHOP_MENU_ART[type][index],240),'남은 경비 '+j.budget,null,'주문 완료');}else toast(result.message);return;}
 if(b.id==='board-journey'){startFlight();return;}
 if(b.id==='immigration-open'){entryPurpose=entryHotel=null;walkTarget=75;immigrationModal();return;}
 if(b.dataset.entryPurpose){entryPurpose=b.dataset.entryPurpose;document.querySelectorAll('[data-entry-purpose]').forEach(x=>x.classList.toggle('selected',x===b));return;}
 if(b.dataset.entryHotel){entryHotel=b.dataset.entryHotel;document.querySelectorAll('[data-entry-hotel]').forEach(x=>x.classList.toggle('selected',x===b));return;}
 if(b.id==='entry-submit'){const result=immigration(j,entryPurpose,entryHotel);if(result.ok){close();save();renderJourney();}toast(result.message);return;}
 if(b.dataset.baggage){const result=collectBaggage(j,b.dataset.baggage);if(result.ok){walkTarget=125;save();renderJourney();}toast(result.message);return;}
 if(b.id==='road-photo'){const kind=j.stage==='to-airport'?'road':'city';if(!j.memories.includes(kind)){j.memories.push(kind);save();toast('차창의 풍경을 여행수첩에 기억했어요.');}else toast('이 길의 풍경은 이미 기억했어요.');return;}
 if(b.dataset.roomKey){if(checkIn(j,b.dataset.roomKey)){walkTarget=185;save();renderJourney();toast('객실 열쇠를 받았어요. 어서 쉬어가요.');if(inviteLocalFriend(j)){save();localFriendVisit();}}else toast('예약한 객실 번호를 다시 확인해요.');return;}
 if(b.dataset.roomTask){if(b.dataset.roomTask==='unpack')return;if(roomTask(j,b.dataset.roomTask)){walkTarget=b.dataset.roomTask==='sleep'?270:185;save();renderJourney(true);ping(520);}return;}
 if(b.dataset.roomItem){selectedRoomItem=b.dataset.roomItem;document.querySelectorAll('[data-room-item]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});document.querySelectorAll('[data-room-spot]').forEach(x=>x.disabled=false);document.querySelector('.room-selection').textContent=roomItemName(selectedRoomItem)+' — 어디에 놓을까요?';return;}
 if(b.dataset.roomSpot){if(!selectedRoomItem){toast('먼저 가방에서 물건을 골라주세요.');return;}const result=placeInRoom(j,selectedRoomItem,b.dataset.roomSpot);if(result.ok){walkTarget={desk:95,bed:265,shelf:140,hanger:280,entry:200}[b.dataset.roomSpot];selectedRoomItem=null;save();renderJourney(true);roomModal();ping(660);}toast(result.message);return;}
 if(b.id==='unpack-done'){if(roomTask(j,'unpack')||j.hotelTask){close();save();renderJourney(true);toast('내 물건들이 놓이니 조금 더 내 방 같아요.');}return;}
 if(b.id==='arrange-again')return;
 if(b.dataset.stay!==undefined){stayModal(+b.dataset.stay);return;}
 if(b.id==='finish-journey'){finishConfirmation();return;}
 if(b.id==='trip-blog'){j=null;home();openPage('blog');return;}
 if(b.id==='trip-home'||b.id==='trip-book'){j=null;home();if(b.id==='trip-book')openPage('passport');return;}
 if(b.id==='cancel-journey'){const returned=returnTripFunds(p,j);j=null;f=null;home();toast('남은 경비 '+returned+'을 여행 지갑에 돌려놓았어요.');return;}
});
let selectedRoomItem=null;
function roomItemName(id){return PACKING.find(x=>x.id===id)?.name||shopItem(id)?.name||id;}
function roomItemIcon(id){return PACKING.find(x=>x.id===id)?.icon||shopIcon(shopItem(id));}
function roomModal(){
 const progress=roomProgress(j),ids=roomItems(j);modal(`<div class="eyebrow">A LITTLE ROOM OF MY OWN</div><h2 id="modal-title">가방에서 방으로</h2><p>물건을 하나 고르고 어울리는 자리에 놓아요.<br>${progress.target}개를 놓으면 정리를 마쳐도 좋아요. 나머지는 천천히.</p><div class="room-progress">놓은 물건 ${progress.placed}/${progress.total}<span>${progress.complete?'작은 정리 완료 ✓':`우선 ${progress.target}개를 놓아봐요`}</span></div><div class="room-items">${ids.map(id=>`<button class="room-item ${selectedRoomItem===id?'selected':''} ${j.roomLayout?.[id]?'placed':''}" data-room-item="${id}" aria-pressed="${selectedRoomItem===id}">${productArt(id,38)}<span>${esc(roomItemName(id))}</span><small>${j.roomLayout?.[id]?ROOM_SPOTS.find(x=>x.id===j.roomLayout[id]).name:'가방 안'}</small></button>`).join('')}</div><p class="room-selection">${selectedRoomItem?esc(roomItemName(selectedRoomItem))+' — 어디에 놓을까요?':'가방 안의 물건을 먼저 골라주세요.'}</p><div class="room-spots">${ROOM_SPOTS.map(spot=>`<button data-room-spot="${spot.id}" ${selectedRoomItem?'':'disabled'}>${pixelIcon(spot.icon)}<span>${spot.name}<small>${spot.hint}</small></span><b>${Object.values(j.roomLayout||{}).filter(id=>id===spot.id).length}/${spot.capacity}</b></button>`).join('')}</div><button id="unpack-done" class="primary" ${progress.complete?'':'disabled'}>${j.hotelTask?'정리 마치고 방으로':'정리 마치기 · 편안함 +15'}</button><button class="secondary" data-close>잠깐 방으로 돌아가기</button>`);
}
$('travel-scene').addEventListener('pointerdown',event=>{if(!j||j.ride)return;const box=event.currentTarget.getBoundingClientRect();if(j.hotelLocation==='neighborhood'){walkToPoint(j,(event.clientX-box.left)/box.width*360,(event.clientY-box.top)/box.height*240);save();}else walkTarget=Math.max(40,Math.min(290,(event.clientX-box.left)/box.width*360));});

$('scene-look').onclick=windowLook;
function wishPicker(){return `<h3 class="section-title">오늘은 어떤 <b>여행</b>을 할까요?</h3><div class="wish-choices">${TRAVEL_WISHES.map(w=>`<button class="wish-choice ${p.tripWish===w.id?'selected':''}" data-trip-wish="${w.id}">${pixelIcon(w.icon)}<strong>${wishTitle(w)}</strong><small>${w.description}</small></button>`).join('')}</div><p class="note">작은 바람마다 보너스를 받아요. 다 이루지 않아도 여행은 완성돼요.</p>`;}
function wishRows(){if(!j)return '';const progress=wishProgress({...j,preparedCount:packingGoals(j).filter(Boolean).length},f);if(!progress)return '';return `<h3 class="section-title">${progress.wish.name} · ${progress.count}/3</h3>${progress.wish.goals.map((goal,i)=>`<div class="goal-row"><span>${progress.done[i]?'✓':'□'}</span><div>${goal}</div></div>`).join('')}<p class="note">하나마다 10 XP · 5머니, 셋 다 이루면 20 XP · 10머니 추가.</p>`;}
$('journey-wish').onclick=()=>modal(`<div class="eyebrow">A WISH FOR TODAY</div><h2 id="modal-title">오늘의 여행에 담고 싶은 것</h2>${wishRows()}<button class="primary" data-close>천천히 여행하기</button>`);

function hotelHTML(){if(j.checkedIn&&j.hotelLocation==='neighborhood')return `<h2>${route(j.routeId).name}의 작은 산책</h2><p class="intro">여행 ${j.nights||1}일째 · 가고 싶은 건물이나 바닥을 누르면 걸어가요.<br>명소·식당·카페·편의점에 들르거나 숙소로 돌아갈 수 있어요.</p>${experiencePanel(p,j)}<div class="local-stop-list">${neighborhoodPlaces(j.routeId).map(x=>`<button data-local-place="${x.id}">${x.name}</button>`).join('')}</div>`;if(j.checkedIn&&j.hotelLocation==='lobby')return `<h2>숙소 로비</h2><p class="intro">객실과 숙소 주변을 자유롭게 오가요.</p><div class="local-stop-list"><button id="return-room">내 객실로</button><button id="city-walk">숙소 밖 산책</button><button id="convenience-open">로비 편의점</button></div>`;const base=hotelBaseHTML();if(!j.checkedIn)return base;const friend=animalEncounter(j);return base+experiencePanel(p,j)+`<p class="note">여행 ${j.nights||1}일째 · 마음에 들면 하루씩 더 묵을 수 있어요.</p><div class="local-stop-list"><button id="city-walk">숙소 주변 산책</button><button id="hotel-lobby">숙소 로비</button><button id="convenience-open">숙소 편의점</button><button id="extra-night">하루 더 묵기</button></div>${friendEventAvailable(j)?`<button id="local-friend-visit" class="secondary">멕시코의 친구 · 서리라</button>`:''}${friend?`<button id="animal-visit" class="secondary">${friend.name} 만나기</button>`:''}`;}
function passportHTML(){return `<div class="collection-intro"><h3>도시마다, 새로운 기억</h3><p>음식·디저트·카페 ${Object.keys(p.discoveries).filter(id=>/:(meal|dessert|cafe)$/.test(id)).length}/93 · 명소 ${Object.keys(p.discoveries).filter(id=>/:place-/.test(id)).length}/62<br>만난 동물 ${Object.keys(p.animals).length}/31</p><button id="discovery-book" class="secondary">맛과 풍경 · 친구 수첩 펼치기</button><button id="local-album" class="secondary">현지 사진 · 추억 페이지 ${p.travel.pages.length}/31</button><button id="offline-download" class="secondary">모든 여행지 오프라인으로 받기</button><div class="save-tools"><button id="save-export" class="secondary">기록 파일 내보내기</button><button id="save-import" class="secondary">기록 가져오기</button></div><input type="file" id="save-file" accept=".json,application/json"></div>`+passportBaseHTML();}
async function cityWalk(){const id=j.id;await atlasReady([...new Set(localItems(j.routeId).map(x=>discoveryAsset(x.id).file))]);if(!j||j.id!==id||j.stage!=='hotel')return;close();j.hotelLocation='neighborhood';resetWalk(j);save();renderJourney();}
function discoveryChoices(items){return items.map(item=>{const used=j.discovered?.includes(item.id);return `<button class="discovery-option" data-discover="${item.id}" ${canDiscover(j,item.id).ok?'':'disabled'}>${discoveryArt(item,74)}<span><strong>${item.name}</strong><small>${used?'이번 여행에 수집':item.cost?item.cost+' 경비':'무료 산책'}</small></span><b>${used?'✓':item.kind==='place'?'둘러보기':'맛보기'}</b></button>`;}).join('');}
function localFriendVisit(topicId=null){if(!friendEventAvailable(j))return;inviteLocalFriend(j);save();const event=j.friendEvent,topic=FRIEND_TOPICS.find(t=>t.id===topicId),met=event.met;modal(`<div class="eyebrow">MEXICO · A FRIEND FROM HOME</div><h2 id="modal-title">${topic?topic.label:'멕시코에서 만난 서리라'}</h2><div class="local-friend-profile">${friendPortrait()}<div><strong>서리라</strong><p>한국인 여성 · 멕시코 취업<br>직장인 · 기혼<br>남편은 현지 한식당을 운영해요.</p></div></div><div class="friend-dialogue"><strong>서리라</strong><p>${topic?topic.lines.join('<br><br>'):met?'반가워! 오늘은 어떤 이야기를 나눠볼까?':'멕시코까지 오느라 고생했어! 나는 여기서 회사에 다니고 있어. 마침 퇴근했는데, 시간 괜찮으면 같이 만나자.'}</p></div>${!met?'<button class="primary" data-local-friend="greet">반갑게 인사하기</button>':topic?'<button class="primary" id="local-friend-visit">다른 이야기 나누기</button>':FRIEND_TOPICS.map(t=>`<button class="secondary" data-local-friend="${t.id}" ${event.topics.includes(t.id)?'disabled':''}>${t.label}${event.topics.includes(t.id)?' ✓':''}</button>`).join('')}<p class="note">${met?'친구와 나눈 기억은 여행수첩과 블로그에 남아요.':'만남 +20 XP · +10머니 / 새 이야기마다 +10 XP'}<br>친구와의 시간은 경비 없이 즐길 수 있어요.</p><button class="secondary" data-close>숙소로 돌아가기</button>`,false);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='local-friend-visit'){localFriendVisit();return;}if(b.dataset.localFriend){const result=visitLocalFriend(p,j,b.dataset.localFriend);if(result.ok){save();renderJourney(true);localFriendVisit(result.topic?.id||null);toast(result.message);ping();}else toast(result.message);}});
function animalVisit(){const a=animalEncounter(j);if(!a)return;modal(`<div class="eyebrow">AN UNEXPECTED FRIEND</div><h2 id="modal-title">${a.name}</h2><canvas class="animal-portrait" width="180" height="210" data-animal-canvas="${a.sprite}" data-animal-hue="${a.hue}"></canvas><p>${a.note}</p><p class="note">${a.sprite===12?'보호 쉼터에서 준비한 대나무 간식으로 교감해요.':'작은 친구와 잠깐 마음을 나누어요.'}<br>잠깐의 만남도 여행의 추억이 돼요.</p><button class="secondary" data-animal-action="watch" ${j.animalMet?'disabled':''}>${j.animalMet?'수첩에 담았어요 ✓':'조용히 인사하고 수첩에 담기'}</button><button class="primary" data-animal-action="feed" ${j.bag.includes('animal-treat')&&!j.animalFed?'':'disabled'}>${j.animalFed?'간식을 나누었어요 ♥':j.bag.includes('animal-treat')?a.sprite===12?'대나무 간식 나누기':'챙겨 온 동물 간식 나누기':'집에서 동물 간식을 챙기면 교감할 수 있어요'}</button>${j.animalFed?'<button class="secondary" id="animal-feed-memory">간식 먹는 모습 다시보기</button>':''}<button class="secondary" data-close>내 방으로 돌아가기</button>`,false);drawAnimalElements();}
function discoveryBook(){modal(`<div class="eyebrow">TASTE · PLACES · FRIENDS</div><h2 id="modal-title">31곳의 기억 수첩</h2><p>도시를 골라 음식, 명소, 동물 기록을 펼쳐보세요.</p><div class="route-grid">${ROUTES.map(r=>{const city=CITY_DISCOVERIES[r.id],count=[...city.foods,...city.places].filter(i=>p.discoveries[i.id]).length;return `<button class="route-card" data-city-book="${r.id}"><span>${r.code}</span><strong>${destinationLabel(r.id)}</strong><small>맛과 풍경 ${count}/5${p.animals[city.animal.id]?' · 친구 ♥':''}</small></button>`;}).join('')}</div><button class="primary" data-close>수첩 닫기</button>`,false);}
function cityBook(id){const city=CITY_DISCOVERIES[id],friend=p.animals[city.animal.id];modal(`<div class="eyebrow">${route(id).code} · ${city.fantasy?'상상 속 여행':'여행의 기억'}</div><h2 id="modal-title">${destinationLabel(id)}</h2>${[...city.foods,...city.places].map(item=>{const record=p.discoveries[item.id];return `<div class="discovery-option ${record?'remembered':'unseen'}">${discoveryArt(item,74)}<span><strong>${item.name}</strong><small>${record?record.count+'번의 기억 · '+new Date(record.date).toLocaleDateString('ko-KR'):'아직 수집하지 않았어요'}</small></span><b>${record?'✓':'—'}</b></div>`;}).join('')}<h3>우연히 만난 친구</h3>${friend?`<canvas class="animal-portrait" width="120" height="140" data-animal-canvas="${city.animal.sprite}" data-animal-hue="${city.animal.hue}"></canvas><p>${city.animal.name}<br>만남 ${friend.count}회 · 간식을 나눈 교감 ${friend.bond}회</p>`:'<p class="note">여행 중 우연히 동물을 만나면 이곳에 기록돼요.</p>'}${id==='mex'?friendNotebookHTML(p.friends?.seorira):''}<button id="discovery-book" class="primary">다른 도시 펼치기</button><button class="secondary" data-close>수첩 닫기</button>`,false);drawAnimalElements();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='city-walk')cityWalk();else if(b.id==='animal-visit')animalVisit();else if(b.id==='discovery-book')discoveryBook();else if(b.dataset.cityBook)cityBook(b.dataset.cityBook);else if(b.dataset.discover){discoveryDetail(b.dataset.discover);}else if(b.dataset.animalAction){const result=meetAnimal(p,j,b.dataset.animalAction==='feed');if(result.ok){save();renderJourney(true);if(result.feed)animalFeeding(result.animal);else animalVisit();toast(result.message);ping();}}});

function productArt(id,size=48){const item=shopItem(id);if(item?.category==='magnet'&&!dutyProductArt(id,size)){const region=item.region;return `<span class="regional-magnet" style="width:${size}px;height:${size}px">${region==='incheon'?'<img src="./assets/incheon-observatory-v6.5.png" alt="">':atlasArt(discoveryAsset(region+':place-0'),size-8)}<small>${region==='incheon'?'ICN':route(region).code}</small></span>`;}const generated=dutyProductArt(id,size);if(generated)return generated;return caseAsset(id)?atlasArt(caseAsset(id),size):itemArt(id,size);}
function drawResidencePreview(){
 if(page!=='residence')return;const canvas=$('residence-preview');if(!canvas)return;
 const paint=()=>{if(page!=='residence'||$('residence-preview')!==canvas)return true;const c=canvas.getContext('2d');c.clearRect(0,0,720,480);c.save();c.scale(2,2);const ready=drawResidence(c,p,performance.now()/1000);c.restore();return ready;};
 paint();homeArtReady(p).then(paint);
}

let windowLookContext=null;
function windowLook(){
 if(j&&['airport','arrival'].includes(j.stage)){airportLook();return;}
 const isResidence=page==='residence',isHome=isResidence||!j||['packing','to-airport'].includes(j.stage),city=isHome?HOME_CITIES.find(x=>x.id===p.residence.city):route(j.routeId);
 windowLookContext={isHome,routeId:isHome?null:j.routeId,night:isHome?p.departure==='night':j.departure==='night'};
 modal(`<div class="eyebrow">A QUIET WINDOW</div><h2 id="modal-title">${city.name}의 창밖 풍경</h2><canvas id="window-glimpse" class="window-glimpse" width="720" height="480" aria-label="${city.name}의 창밖 풍경"></canvas><p>${isHome?city.view:'창 너머로 천천히 흐르는 '+city.name+'의 풍경이에요.'}</p><button class="primary" data-close>${isResidence?'나의 집으로 돌아가기':'여행으로 돌아가기'}</button>`,false);
 atlasReady(isHome?['home-views-v6.png']:[discoveryAsset(windowLookContext.routeId+':place-1').file]).then(()=>paintWindowLook());
}
function paintWindowLook(){
 const canvas=$('window-glimpse'),context=windowLookContext;if(!canvas||$('modal').hidden||!context)return;
 const t=performance.now()/1000;if(context.isHome){const c=canvas.getContext('2d');c.clearRect(0,0,720,480);c.fillStyle='#e5e4d6';c.fillRect(0,0,720,480);drawHomeWindow(c,p,t,[40,40,640,388],true);}else drawDestinationWindow(canvas,context.routeId,t,context.night);
}
homeArtReady(p);
for(const [id,name] of [['wardrobe-icon','wardrobe'],['book-icon','passport'],['help-icon','help'],['home-design-icon','home']])$(id).innerHTML=navArt(name,34);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='residence-look'){windowLook();}else if(b.dataset.homeCategory){homeCategory=b.dataset.homeCategory;renderPage(true);homeArtReady(p,homeCategory).then(drawResidencePreview);}else if(b.dataset.homeTab){homeTab=b.dataset.homeTab;renderPage(true);}else if(b.dataset.homeChoice){const kind=b.dataset.homeKind,id=b.dataset.homeChoice,result=homePurchase(p,kind,id);if(result.ok){save();currencies();renderPage(true);if(result.cost>0){const item=HOME_FURNITURE.find(x=>x.id===id);purchaseComplete(kind==='furniture'?item.name:'나의 집 꾸미기',kind==='furniture'?atlasArt(furnitureAsset(id),240,item.name):'<canvas id="purchase-home-preview" width="720" height="480" class="cabin-choice-preview" aria-label="구매 후 적용된 나의 집"></canvas>',result.message+' · 남은 머니 '+p.coins);if(kind!=='furniture'){const paint=()=>{const canvas=$('purchase-home-preview');if(canvas){const c=canvas.getContext('2d');c.save();c.scale(2,2);drawResidence(c,p,performance.now()/1000);c.restore();}};paint();homeArtReady(p).then(paint);}}else toast(result.message);}else toast(result.message);}});
import {SEORIRA,FRIEND_TOPICS,friendEventAvailable,inviteLocalFriend,visitLocalFriend,friendPortrait,friendNotebookHTML} from './local-friends.js?v=6.7.0';

import {dutyProductArt} from './duty-art.js?v=6.7.0';

function wishTitle(w){const key={scenery:'풍경',cozy:'푹 쉬는',thrifty:'가볍게',gifts:'선물'}[w.id];return w.name.replace(key,'<b class="keyword">'+key+'</b>');}
function paintFlight(){if(view==='seat')drawCabinView($('scenery'),f,p,performance.now()/1000);else drawScenery($('scenery'),renderFlight(),f.elapsed);}
function finishConfirmation(){modal(composeHTML(p,j),false);}
function discoveryDetail(id,finished=false){const item=DISCOVERY_ITEMS.find(x=>x.id===id&&id.startsWith(j.routeId+':'));if(!item)return;const check=canDiscover(j,id);modal(`<div class="eyebrow">${destinationLabel(j.routeId)}</div><h2 id="modal-title">${item.name}</h2><div class="art-showcase">${discoveryArt(item,260)}</div><p>${finished?item.note:item.kind==='cafe'?localFlavor(j.routeId).cafe+'에 들러 잠깐 쉬어요.':item.kind==='place'?'잠시 걸음을 멈추고 풍경을 바라봐요.':'이 지역의 맛을 천천히 즐겨요.'}<br>${item.cost?item.cost+' 경비':'무료 산책'}</p>${!finished?`<button class="primary" data-discover-confirm="${id}" ${check.ok?'':'disabled'}>${check.ok?item.kind==='place'?'둘러보고 기억하기':'맛보고 기억하기':'오늘 이미 즐겼어요'}</button>`:'<p class="note">오늘의 기억이 여행수첩에 담겼어요.</p>'}<button class="secondary" data-close>산책으로 돌아가기</button>`,false);}
function purchaseComplete(name,picture,note,returnId=null,heading='구매 완료'){
 modal(`<div class="eyebrow">${heading==='주문 완료'?'ORDER COMPLETE':'PURCHASE COMPLETE'}</div><h2 id="modal-title">${heading}</h2><p class="purchased-name">${esc(name)}</p><div class="art-showcase purchased-showcase" aria-label="${esc(name)} 구매 완료 이미지">${picture}</div><p>${esc(note)}</p><button class="primary" ${returnId?'id="'+returnId+'"':'data-close'}>${returnId?'매장으로 돌아가기':page==='residence'?'나의 집으로 돌아가기':'돌아가기'}</button>`,false);ping(760);
}

let localCameraPlace=null,localCameraFrame='wide',displaySlot=0;
function openLocalCamera(){if(!j||j.stage!=='hotel'||!j.checkedIn)return;const visits=experience(j).visits;if(!visits.length){toast('먼저 동네에서 가게나 명소 한 곳을 둘러봐요.');return;}if(!visits.includes(localCameraPlace))localCameraPlace=visits.at(-1);modal(cameraHTML(j,localCameraPlace,localCameraFrame),false);document.querySelectorAll('[data-camera-place]').forEach(b=>b.disabled=!visits.includes(b.dataset.cameraPlace));}
function showCityEpisode(){const e=experience(j),ep=CITY_EPISODES[j.routeId];if(!episodeReady(j))return;modal(`<h2 id="modal-title">${ep.event}</h2><div class="art-showcase">${discoveryArt(localItems(j.routeId).find(x=>x.id===e.plan[0]),230)}</div><p>${ep.intro}</p>${ep.choices.map((text,i)=>`<button class="secondary" data-episode-choice="${i}">${text}</button>`).join('')}<p class="note">고른 기억이 블로그와 여행수첩에 남아요. 선택에 따라 다음 날의 이야기가 이어져요.</p><button class="secondary" data-close>조금 더 생각하기</button>`,false);}
function localAlbum(){modal(`<h2 id="modal-title">현지에서 남긴 사진</h2><p>추억 페이지 ${p.travel.pages.length}/31 · 두 장소와 사진, 이야기를 모아 완성해요.</p><div class="memory-display-grid">${p.travel.photos.slice().reverse().map(x=>`<button data-album-memory="${esc(x.id)}">${photoPicture(x,90)}<small>${destinationLabel(x.route)}</small></button>`).join('')}</div>${!p.travel.photos.length?'<p>숙소 주변을 산책하고 사진 남기기를 눌러보세요.</p>':''}<button class="primary" data-close>수첩으로 돌아가기</button>`,false);}
function openDisplay(){modal(displayHTML(p,displaySlot,productArt),false);}
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.planPick){const selected=p.travelPlans[p.route]||planFor(p.route,p.tripWish),id=b.dataset.planPick;p.travelPlans[p.route]=selected.includes(id)?selected.filter(x=>x!==id):[...selected.slice(-1),id];if(p.travelPlans[p.route].length<2)p.travelPlans[p.route]=[id,...localItems(p.route).filter(x=>x.id!==id).slice(0,1).map(x=>x.id)];save();renderPage(true);return;}
 if(b.id==='edit-itinerary'){modal(`<h2 id="modal-title">오늘의 동선</h2><p>순서대로 가고 싶은 두 곳을 골라요. 다른 곳도 자유롭게 들러요.</p><div class="memory-picks">${localItems(j.routeId).map(x=>`<button data-journey-plan="${x.id}" class="${experience(j).plan.includes(x.id)?'selected':''}">${esc(x.name)}</button>`).join('')}</div><button class="primary" data-close>이 동선으로 산책하기</button>`,false);return;}
 if(b.dataset.journeyPlan){selectPlan(j,b.dataset.journeyPlan);if(experience(j).plan.length<2){const other=localItems(j.routeId).find(x=>!experience(j).plan.includes(x.id));experience(j).plan.push(other.id);}save();renderJourney(true);document.querySelectorAll('[data-journey-plan]').forEach(x=>x.classList.toggle('selected',experience(j).plan.includes(x.dataset.journeyPlan)));return;}
 if(b.id==='day-rest'){j.comfort=Math.min(100,j.comfort+3);advanceDay(j);save();renderJourney(true);toast(DAY_PHASES[experience(j).phase]+'의 풍경을 천천히 바라봐요.');return;}
 if(b.id==='local-camera'){openLocalCamera();return;}
 if(b.dataset.cameraPlace){localCameraPlace=b.dataset.cameraPlace;openLocalCamera();return;}
 if(b.dataset.cameraFrame){localCameraFrame=b.dataset.cameraFrame;openLocalCamera();return;}
 if(b.id==='local-shutter'){const result=takeLocalPhoto(p,j,localCameraPlace,localCameraFrame);if(result){claimPage(p,j);save();renderJourney(true);modal(`<h2 id="modal-title">${result.isNew?'새로운 사진을 남겼어요':'이 순간은 수첩에 담겨 있어요'}</h2>${photoPicture(result.photo,260)}<p>나의 집에서 액자로 전시할 수 있어요.</p><button class="primary" data-close>산책으로 돌아가기</button>`,false);ping(1050);}return;}
 if(b.id==='city-episode'){showCityEpisode();return;}
 if(b.dataset.episodeChoice!==undefined){if(chooseEpisode(p,j,+b.dataset.episodeChoice)){claimPage(p,j);save();renderJourney(true);close();toast(CITY_EPISODES[j.routeId].choices[experience(j).choice]+' · 새로운 이야기를 남겼어요.');}return;}
 if(b.id==='episode-follow'){if(followEpisode(p,j)){save();renderJourney(true);const ep=CITY_EPISODES[j.routeId],e=experience(j);modal(`<h2 id="modal-title">${ep.followTitle}</h2><p>${e.choice===0?'어제 기록한 장면을 다시 찾아왔어요.':'어제 쉬었던 자리로 다시 걸어왔어요.'}<br><br>${ep.follow}</p><button class="primary" data-close>다음 산책 이어가기</button>`,false);}return;}
 if(b.dataset.memoryPick){const e=experience(j),id=b.dataset.memoryPick;if(e.highlights.length===1&&e.highlights.includes(id)){toast('글에 남길 기억을 한 가지는 골라주세요.');return;}e.highlights=e.highlights.includes(id)?e.highlights.filter(x=>x!==id):[...e.highlights.slice(-2),id];save();finishConfirmation();return;}
 if(b.id==='local-album'){localAlbum();return;}
 if(b.dataset.albumMemory){const photo=p.travel.photos.find(x=>x.id===b.dataset.albumMemory);if(photo)modal(`<h2 id="modal-title">${destinationLabel(photo.route)}의 한 장</h2>${photoPicture(photo,280)}<button class="primary" id="local-album">다른 사진 보기</button><button class="secondary" data-close>닫기</button>`,false);return;}
 if(b.id==='memory-display'){openDisplay();return;}
 if(b.dataset.displaySlot!==undefined){displaySlot=+b.dataset.displaySlot;openDisplay();return;}
 if(b.dataset.displayMemory){if(displayMemory(p,b.dataset.displayMemory,displaySlot)){save();drawResidencePreview();toast('집에 여행의 기억을 전시했어요.');}return;}
 if(b.id==='clear-display'){displayMemory(p,null,displaySlot);save();drawResidencePreview();toast('전시 자리를 비웠어요.');return;}
 if(b.id==='offline-download'){if(!navigator.serviceWorker?.controller){toast('웹에서 한 번 새로고침한 뒤 사용할 수 있어요. 앱은 모든 풍경이 포함돼 있어요.');return;}b.disabled=true;b.textContent='풍경 받는 중…';navigator.serviceWorker.controller.postMessage({type:'DOWNLOAD_ALL'});return;}
 if(b.id==='save-export'){save();if(window.TravelFiles?.saveRecord){window.TravelFiles.saveRecord(exportSave(p));return;}const blob=new Blob([exportSave(p)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='여행게임-기록-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('여행 기록 파일을 내보냈어요.');return;}
 if(b.id==='save-import'){$('save-file').click();return;}
 if(b.id==='confirm-save-import'){const text=$('import-record-text').value;try{const restored=importSave(text);save();localStorage.setItem(KEY+'-before-import',JSON.stringify(p));p=restored;f=p.active;j=p.journey;pausedAt=0;save();location.reload();}catch(error){toast(error.message);}return;}
});
document.addEventListener('change',async event=>{if(event.target.id!=='save-file')return;const file=event.target.files[0];if(!file)return;try{if(file.size>4000000)throw new Error('기록 파일 크기를 확인해주세요.');const text=await file.text(),restored=importSave(text);modal(`<h2 id="modal-title">여행 기록을 가져올까요?</h2><p>${esc(restored.name)} · 여행 ${restored.journeys}회<br>현지 사진 ${restored.travel.photos.length}장 · 추억 페이지 ${restored.travel.pages.length}개<br>현재 기록은 교체 전에 별도로 보관해요.</p><textarea id="import-record-text" hidden></textarea><button id="confirm-save-import" class="primary">이 기록으로 이어서 플레이하기</button><button class="secondary" data-close>돌아가기 · 현재 기록 유지</button>`,false);$('import-record-text').value=text;}catch(error){toast(error.message);}event.target.value='';});
function purchaseDetail(id){const item=shopInventory(j).find(x=>x.id===id);if(!item)return;const check=canPurchase(j,id);modal(`<h2 id="modal-title">${item.name}</h2><div class="purchase-summary">${productArt(id,56)}</div><p>${item.cost} 경비 · ${item.minutes}분<br>${item.category==='magnet'?'이 공항에서만 만나는 지역 한정 기념품이에요.':itemEffect(item)}</p><button class="primary" data-purchase-confirm="${id}" ${check.ok?'':'disabled'}>이 물건 구매하기</button><button class="secondary" id="shop-return">돌아가기</button>`);}
let airportLookContext=null;
function airportLook(view){
 const context=observatoryContext(j,view);if(!context)return;airportLookContext=context;const {region,local}=context,name=local?route(region).name:'인천 국제공항';
 modal(`<div class="eyebrow">AIRPORT OBSERVATORY</div><h2 id="modal-title">${name} 공항 전망대</h2><canvas id="airport-panorama" width="720" height="480" class="window-glimpse" aria-label="${name} ${context.view==='regional'?'지역 전망':'공항 풍경'}"></canvas>${local?`<div class="choice-row"><button data-airport-view="regional" aria-pressed="${context.view==='regional'}">${name} 풍경</button><button data-airport-view="terminal" aria-pressed="${context.view==='terminal'}">공항 전경</button></div>`:''}<p>${local?context.view==='regional'?name+'에 도착했어요. 이 지역의 하늘과 풍경을 크게 감상해요.':cityCaption(region).airport:'관제탑과 활주로, 탑승을 준비하는 비행기를 바라봐요.'}</p><button class="primary" data-close>공항으로 돌아가기</button>`,false);
 if(j.stage==='airport'&&j.airport.security&&!j.memories.includes('airport')){const result=airportAction(j,'postcard');if(result.ok){save();renderJourney(true);}}
 if(local){(context.view==='regional'?localObservatoryReady(region):cityArtReady([region],['airport'])).then(()=>{if(airportLookContext===context)paintAirportLook(performance.now());});paintAirportLook(performance.now());}
 else {const im=new Image();im.onload=()=>{const canvas=$('airport-panorama');if(canvas&&airportLookContext===context)canvas.getContext('2d').drawImage(im,0,0,720,480);};im.src='./assets/incheon-observatory-v6.5.png';}
}
function paintAirportLook(ts){const canvas=$('airport-panorama'),context=airportLookContext;if(!canvas||$('modal').hidden||!context?.local)return;if(context.view==='regional')drawLocalObservatory(canvas,context.region,context.night,ts/1000);else drawCityPanel(canvas.getContext('2d'),context.region,'airport',0,[0,0,720,480]);}
function enterNeighborhoodPlace(id){j.lastPlace=id;if(id==='hotel'){j.hotelLocation='room';resetWalk(j);save();renderJourney();return;}if(id==='convenience'){convenienceModal();return;}save();discoveryDetail(id);}
function convenienceModal(){modal(`<h2 id="modal-title">${j.hotelLocation==='neighborhood'?'동네':'숙소'} 편의점</h2><p>남은 경비 ${j.budget} · 오늘 필요한 것만 골라요.</p>${CONVENIENCE_ITEMS.map(x=>`<button class="transport-option" data-convenience="${x.id}" ${j.convenienceToday?.includes(x.id)?'disabled':''}>${itemArt(x.art,54)}<span>${x.name}<small>${x.cost} 경비 · ${j.convenienceToday?.includes(x.id)?'오늘 구매 완료':'자세히 보기'}</small></span></button>`).join('')}<button class="secondary" data-close>돌아가기</button>`,false);}
function extraNightModal(){const cost=HOTELS.find(x=>x.id===j.hotel).cost,deficit=Math.max(0,cost-j.budget);modal(`<h2 id="modal-title">하루 더 머물까요?</h2><p>현재 ${j.nights||1}일째 · 숙박비 ${cost} 경비<br>남은 경비 ${j.budget}${deficit?' · 블로그 지갑에서 '+deficit+' 사용':''}<br>잠을 자면 다음 날 다시 음식과 카페를 즐길 수 있어요.</p><button id="confirm-extra-night" class="primary" ${(j.nights||1)>=30||deficit>p.blog.wallet?'disabled':''}>하루 더 자고 다음 날 맞기</button><button class="secondary" data-close>돌아가기</button>`,false);}
let cinemaSession=null;
const teaPairs=[['tea','cake'],['latte','bread'],['cocoa','cookie']],amenityFiles=['mask','lipbalm','towel'];
function cabinServices(){const services=CABIN_EXPERIENCES[f.cabin]||[];modal(`<h2 id="modal-title">${cabin(f.cabin).name}에서의 시간</h2><p>${f.cabin==='business'?'넓은 좌석과 침대 모드, 작은 여행 도구와 기내 영상.':'조용한 스위트와 침구, 원하는 시간의 티·디저트.'}</p><div class="cabin-service-grid">${services.map(x=>`<button data-cabin-service="${x.id}">${x.name}<small>${f.experiences?.[x.id]?'다시 즐기기 · '+f.experiences[x.id]:'골라서 즐기기'}</small></button>`).join('')}</div><button class="secondary" data-close>좌석으로 돌아가기</button>`);}
function serviceArt(id,i,size=64){return id==='tea'?teaPairs[i].map(x=>itemArt('meal-'+x,size)).join(''):id==='amenity'?`<img class="amenity-picture" width="${size}" height="${size}" src="./assets/amenity-${amenityFiles[i]}-v6.5.png" alt="">`:'';}
function cabinServiceDetail(id){
 const item=CABIN_EXPERIENCES[f.cabin]?.find(x=>x.id===id);if(!item)return;
 const selected=Math.max(0,item.choices.indexOf(f.experiences?.[id])),theme=item.choices[selected];
 if(id==='cinema')cinemaSession={theme,started:performance.now(),offset:.65,paused:false};
 const preview=['tea','amenity'].includes(id)?`<div class="art-showcase cabin-choice-showcase ${id}">${serviceArt(id,selected,220)}</div>`:id==='cinema'?`<figure class="cinema-screen"><canvas id="cinema-screen" width="960" height="540" role="img" aria-label="여행 시네마 미리보기"></canvas><figcaption id="cinema-caption"></figcaption></figure>`:'<canvas class="cabin-choice-preview" id="cabin-choice-preview" width="720" height="480" role="img" aria-label="좌석 서비스 미리보기"></canvas>';
 modal(`<h2 id="modal-title">${item.name}</h2>${preview}<p>${item.note}</p><div class="cabin-service-grid">${item.choices.map((choice,i)=>`<button data-cabin-choice="${id}" data-choice-index="${i}">${serviceArt(id,i)}<span>${choice}</span>${f.experiences?.[id]?'<small>이미지를 다시 볼 수 있어요</small>':''}</button>`).join('')}</div><button class="secondary" id="cabin-services">돌아가기</button>`);
 if(id==='cinema')cinemaReady(theme).then(()=>paintCinema(performance.now()));else paintCabinPreview(performance.now());
}
function cabinServiceResult(id,choice,i,result){
 const item=result.item;
 if(id==='cinema'){
  cinemaSession={theme:choice,started:performance.now(),offset:0,paused:false};
  modal(`<div class="eyebrow">${f.cabin==='first'?'PRIVATE':'IN-FLIGHT'} CINEMA</div><h2 id="modal-title">${choice}</h2><figure class="cinema-screen"><canvas id="cinema-screen" width="960" height="540" role="img" aria-label="${choice} 상영 화면"></canvas><figcaption id="cinema-caption"></figcaption></figure><p class="note">여행 그림이 천천히 움직이며 9초마다 다음 장면으로 이어져요.</p><div class="cinema-controls"><button id="cinema-pause" aria-pressed="false">일시정지</button><button id="cinema-next">다음 장면</button></div><p class="note">${esc(result.message)}</p><button class="secondary" id="cabin-services">서비스로 돌아가기</button><button class="primary" data-close>좌석으로 돌아가기</button>`);
  cinemaReady(choice).then(()=>paintCinema(performance.now()));paintCinema(performance.now());return;
 }
 modal(`<h2 id="modal-title">${choice}</h2>${['tea','amenity'].includes(id)?`<div class="art-showcase cabin-choice-showcase ${id}">${serviceArt(id,i,220)}</div>`:'<canvas class="cabin-choice-preview" id="cabin-choice-preview" width="720" height="480" role="img" aria-label="'+esc(choice)+'"></canvas>'}<p>${item.note}</p><p class="note">${esc(result.message)}</p><button class="secondary" data-cabin-service="${id}">다른 선택 보기</button><button class="primary" data-close>좌석으로 돌아가기</button>`);paintCabinPreview(performance.now());
}
function paintCabinPreview(ts){const canvas=$('cabin-choice-preview');if(canvas&&!$('modal').hidden&&f)drawCabinView(canvas,f,p,ts/1000);}
function cinemaTime(ts){return cinemaSession?cinemaSession.offset+(cinemaSession.paused?0:(ts-cinemaSession.started)/1000):0;}
function paintCinema(ts){const canvas=$('cinema-screen');if(!canvas||$('modal').hidden||!cinemaSession)return;const frame=drawCinema(canvas,cinemaSession.theme,cinemaTime(ts));$('cinema-caption').textContent=`${frame.shot.title} · ${frame.index+1} / ${frame.count}`;}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.id==='confirm-finish'){setHighlights(j,p,experience(j).highlights);completeJourney();return;}
 if(b.id==='extra-night'){extraNightModal();return;}
 if(b.id==='confirm-extra-night'){const cost=HOTELS.find(x=>x.id===j.hotel).cost,deficit=Math.max(0,cost-j.budget);if(deficit>p.blog.wallet||(j.nights||1)>=30)return;p.blog.wallet-=deficit;j.budget+=deficit;const result=extendStay(j,cost);if(!result.ok){p.blog.wallet+=deficit;j.budget-=deficit;}else {close();save();renderJourney();}toast(result.message);return;}
 if(b.id==='hotel-lobby'||b.id==='return-room'){j.hotelLocation=b.id==='hotel-lobby'?'lobby':'room';resetWalk(j);save();renderJourney();return;}
 if(b.dataset.localPlace){const tripId=j?.id,target=b.dataset.localPlace;const go=()=>{if(j?.id===tripId&&walkToPlace(j,target))save();};if(j.hotelLocation!=='neighborhood')cityWalk().then(go);else go();return;}
 if(b.id==='convenience-open'){convenienceModal();return;}
 if(b.dataset.convenience){const item=CONVENIENCE_ITEMS.find(x=>x.id===b.dataset.convenience);if(!item)return;modal(`<h2 id="modal-title">${item.name}</h2><div class="purchase-summary">${itemArt(item.art,56)}</div><p>${item.cost} 경비 · 오늘 필요한 작은 물건이에요.</p><button class="primary" data-convenience-confirm="${item.id}">구매하기</button><button class="secondary" id="convenience-open">돌아가기</button>`,false);return;}
 if(b.dataset.convenienceConfirm){const result=conveniencePurchase(j,b.dataset.convenienceConfirm,bagWeight(j));if(result.ok){save();renderJourney(true);purchaseComplete(result.item.name,itemArt(result.item.art,240),'남은 경비 '+j.budget,'convenience-open');}else toast(result.message);return;}
 if(b.dataset.discoverConfirm){const result=discover(p,j,b.dataset.discoverConfirm);if(result.ok){noteVisit(j,b.dataset.discoverConfirm);claimPage(p,j);close();save();renderJourney(true);ping();}toast(result.message);return;}
 if(b.dataset.purchaseConfirm){const id=b.dataset.purchaseConfirm,result=purchase(p,j,id);if(result.ok){save();renderJourney(true);purchaseComplete(shopItem(id).name,productArt(id,240),'여행가방에 보관했어요. · 남은 경비 '+j.budget,'shop-return');}else toast(result.message);return;}
 if(b.id==='shop-return'){dutyFreeModal();return;}
 if(b.id==='arrival-observatory'){airportLook();return;}
 if(b.dataset.airportView){airportLook(b.dataset.airportView);return;}
 if(b.id==='cabin-services'){cabinServices();return;}
 if(b.dataset.cabinService){cabinServiceDetail(b.dataset.cabinService);return;}
 if(b.id==='cinema-pause'&&cinemaSession){const now=performance.now();cinemaSession.offset=cinemaTime(now);cinemaSession.started=now;cinemaSession.paused=!cinemaSession.paused;b.textContent=cinemaSession.paused?'계속 보기':'일시정지';b.setAttribute('aria-pressed',String(cinemaSession.paused));paintCinema(now);return;}
 if(b.id==='cinema-next'&&cinemaSession){const now=performance.now();cinemaSession.offset=(Math.floor(cinemaTime(now)/9)+1)*9+.65;cinemaSession.started=now;paintCinema(now);return;}
 if(b.dataset.cabinChoice){const id=b.dataset.cabinChoice,i=+b.dataset.choiceIndex,item=CABIN_EXPERIENCES[f.cabin]?.find(x=>x.id===id),choice=item?.choices[i];const result=cabinExperience(f,id,choice);if(result.ok){save();changeView('seat');updateFlight();cabinServiceResult(id,choice,i,result);}else toast(result.message);return;}
});
document.addEventListener('keydown',event=>{if(!j||j.hotelLocation!=='neighborhood'||!$('modal').hidden||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();const pos=j.walkPosition||{x:180,y:225};walkToPoint(j,pos.x+(event.key==='ArrowLeft'?-18:event.key==='ArrowRight'?18:0),pos.y+(event.key==='ArrowUp'?-18:event.key==='ArrowDown'?18:0));});

navigator.serviceWorker?.addEventListener('message',event=>{const d=event.data;if(d?.type!=='OFFLINE_PROGRESS')return;const button=$('offline-download');if(button){button.textContent=d.error?'다시 오프라인으로 받기':d.done?'모든 여행지 오프라인 저장 완료':'풍경 받는 중 · '+d.percent+'%';button.disabled=!d.done&&!d.error;}if(d.error)toast('저장 공간이나 연결 상태를 확인하고 다시 받아주세요.');if(d.done)toast('모든 여행지의 풍경과 음악을 저장했어요.');});
let feedingSession=null;
function animalFeeding(animal){feedingSession={animal,started:performance.now(),phase:null};modal(`<div class="eyebrow">A LITTLE MOMENT TOGETHER</div><h2 id="modal-title">${animal.name}에게 간식을 건네요</h2><canvas id="animal-feeding" class="feeding-scene" width="360" height="260" aria-label="다가와 간식을 오물오물 먹는 ${animal.name}"></canvas><p id="feeding-caption" class="feeding-caption" role="status"></p><p class="note">간식 한 개를 나누었어요. 교감은 여행수첩과 블로그에 남아요.</p><button id="feeding-replay" class="secondary" disabled>간식을 맛보는 중이에요</button><button class="primary" data-close>산책으로 돌아가기</button>`,false);paintAnimalFeeding(performance.now());}
function paintAnimalFeeding(ts){const canvas=$('animal-feeding');if(!canvas||$('modal').hidden||!feedingSession)return;const frame=drawFeeding(canvas,feedingSession.animal,(ts-feedingSession.started)/1000);if(frame.phase!==feedingSession.phase){feedingSession.phase=frame.phase;$('feeding-caption').textContent={offer:'손 위에 간식을 올려 살며시 내밀어요.',approach:'킁킁, 작은 친구가 다가와요.',eat:'오물오물… 간식을 조금씩 먹고 있어요.',happy:'맛있게 다 먹었어요! 마음이 조금 더 가까워졌어요. ♥'}[frame.phase];}if(frame.done){$('feeding-replay').disabled=false;$('feeding-replay').textContent='먹는 모습 한 번 더 보기';}}
document.addEventListener('click',e=>{if(e.target.closest('#animal-feed-memory')&&j?.animalFed){animalFeeding(animalEncounter(j));return;}if(e.target.closest('#feeding-replay')&&!$('feeding-replay').disabled&&feedingSession){feedingSession.started=performance.now();feedingSession.phase=null;$('feeding-replay').disabled=true;$('feeding-replay').textContent='간식을 맛보는 중이에요';paintAnimalFeeding(performance.now());}});
installMoneyUI();
$('updates').onclick=()=>modal(`<div class="eyebrow">TRAVEL GAME · 6.7.0</div><h2 id="modal-title">어디든 떠날 수 있어요</h2><div class="experience-paper"><h3>31개 여행지와 모든 좌석</h3><p>처음부터 모든 목적지와 비즈니스·퍼스트클래스를 골라요. 새 여행자는 1,000머니로 시작해요.</p><h3>눈에 잘 들어오는 여행머니</h3><p>시작 화면과 여행 중에도 돈을 확인해요. 가격, 구매, 보상에는 같은 도트 동전 아이콘을 표시해요.</p><h3>작은 친구와 간식 시간</h3><p>간식을 건네면 동물이 다가와 오물오물 먹고 마음을 나눠요. 먹는 모습은 다시 볼 수 있어요.</p></div><button class="primary" data-close>여행 시작하기</button>`);
